import{_ as e,o as t,c as s,a2 as d}from"./chunks/framework.C2TvIV46.js";const u=JSON.parse('{"title":"Grenade Count","description":"","frontmatter":{},"headers":[],"relativePath":"language/enums/player-traits/grenade-count.md","filePath":"language/enums/player-traits/grenade-count.md"}'),o={name:"language/enums/player-traits/grenade-count.md"};function n(l,a,r,c,p,i){return t(),s("div",null,[...a[0]||(a[0]=[d(`<h1 id="grenade-count" tabindex="-1">Grenade Count <a class="header-anchor" href="#grenade-count" aria-label="Permalink to &quot;Grenade Count&quot;">​</a></h1><p>Value syntax for the <code>initial_grenades</code> field on the <a href="/MegaloEvolved/beta/docs/language/enums/player-traits">Player traits</a> enum. Used inside <a href="/MegaloEvolved/beta/docs/language/elements/game-options/player-traits"><code>player_traits</code></a> blocks and <code>override base_player_traits</code> (and similar) in <a href="/MegaloEvolved/beta/docs/language/elements/game-options"><code>game_options</code></a>.</p><p>ManagedMegalo accepts a single token or a count plus grenade type. Reach scripts use only <strong>frag</strong> and <strong>plasma</strong> counts on the wire (<code>each</code> sets equal counts of both).</p><h2 id="special-values" tabindex="-1">Special values <a class="header-anchor" href="#special-values" aria-label="Permalink to &quot;Special values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>none</code></td><td>No starting grenades</td></tr><tr><td><code>default</code></td><td>Use the map&#39;s default grenade loadout</td></tr></tbody></table><h2 id="count-forms" tabindex="-1">Count forms <a class="header-anchor" href="#count-forms" aria-label="Permalink to &quot;Count forms&quot;">​</a></h2><p>Count must be <strong>1–4</strong>. Type must be <code>frag</code>, <code>plasma</code>, or <code>each</code>.</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Starting grenades</th></tr></thead><tbody><tr><td><code>1 frag</code></td><td>1 frag</td></tr><tr><td><code>2 frag</code></td><td>2 frag</td></tr><tr><td><code>3 frag</code></td><td>3 frag</td></tr><tr><td><code>4 frag</code></td><td>4 frag</td></tr><tr><td><code>1 plasma</code></td><td>1 plasma</td></tr><tr><td><code>2 plasma</code></td><td>2 plasma</td></tr><tr><td><code>3 plasma</code></td><td>3 plasma</td></tr><tr><td><code>4 plasma</code></td><td>4 plasma</td></tr><tr><td><code>1 each</code></td><td>1 frag and 1 plasma</td></tr><tr><td><code>2 each</code></td><td>2 frag and 2 plasma</td></tr><tr><td><code>3 each</code></td><td>3 frag and 3 plasma</td></tr><tr><td><code>4 each</code></td><td>4 frag and 4 plasma</td></tr></tbody></table><p>To mix unequal frag and plasma counts, use <strong>separate lines</strong> — each line updates one side of the loadout:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">override base_player_traits</span></span>
<span class="line"><span class="megalo-text">	initial_grenades </span><span class="megalo-number">1</span><span class="megalo-text"> frag</span></span>
<span class="line"><span class="megalo-text">	initial_grenades </span><span class="megalo-number">1</span><span class="megalo-text"> plasma</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">player_traits infected_traits</span></span>
<span class="line"><span class="megalo-text">	initial_grenades none</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Grenade types in <a href="/MegaloEvolved/beta/docs/language/object-lists"><code>grenades.txt</code></a> (spike, firebomb, etc.) are not valid here; only <code>frag</code>, <code>plasma</code>, and <code>each</code> are accepted by the Megalo parser.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/enums/player-traits">Player traits</a></li><li><a href="/MegaloEvolved/beta/docs/language/elements/game-options/player-traits">player_traits</a></li></ul>`,14)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
